    events: list[dict],
    *,
    min_amount: int = 0,
) -> dict[str, dict[str, int]]:
    if not isinstance(events, list):
        raise TypeError(
            f"events must be a list, got {type(events).__name__!r}"
        )
    if not isinstance(min_amount, int):
        raise TypeError(
            f"min_amount must be an int, got {type(min_amount).__name__!r}"
        )
