        raise ValueError("min_amount must be non-negative")

    for i, event in enumerate(events):
        if not isinstance(event, dict):
            raise TypeError(
                f"each event must be a dict; item at index {i} is "
                f"{type(event).__name__!r}"
            )

    index: dict[str, dict[str, int]] = {}
    for event in events:
        if _is_valid_event(event, min_amount):
            _accumulate_event(index, event)
    return index

